    ('f1000000-0000-0000-0000-000000000094', '2475a3af-237a-48e6-ba96-80961f1dda27', 'a1000000-0000-0000-0000-000000000028', 'Where should my riskiest joke go in a 5-minute set?', false, 'Homework', 0, 'f3000000-0000-0000-0000-000000000094', 1, '2026-05-20 17:06:55+00'::timestamptz + interval '7 seconds'),
    ('f1000000-0000-0000-0000-000000000095', '2475a3af-237a-48e6-ba96-80961f1dda27', 'a1000000-0000-0000-0000-000000000029', 'What exactly counts as the "tag" after a punchline?', false, 'Doubts', 0, 'f3000000-0000-0000-0000-000000000095', 1, '2026-05-20 17:06:55+00'::timestamptz + interval '2119 seconds');
INSERT INTO answers (id, question_id, content, model_used, generation_latency_ms) VALUES
    ('f2000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000001', 'As tight as possible — the setup should contain only what''s strictly necessary for the punchline to land. Every extra word is a chance for the audience to drift before the payoff. For your open mic set, read each setup out loud and cut anything that isn''t doing direct work to set up the twist.', 'gpt-4o', 973),
    ('f2000000-0000-0000-0000-000000000002', 'f1000000-0000-0000-0000-000000000002', 'Four theories: Incongruity (humor from conflicting ideas resolved by the punchline), Superiority (laughing at others'' misfortune or inferiority — Hobbes, Plato), Relief (laughter releasing suppressed tension — Freud, Spencer), and Bergson''s social-corrective theory (laughing at rigidity to nudge people back toward flexibility). Reference whichever framework best explains the specific joke you''re analysing — most jokes lean on more than one.', 'gpt-4o', 989),
    ('f2000000-0000-0000-0000-000000000003', 'f1000000-0000-0000-0000-000000000003', 'Two items just read as a list — there''s no real pattern yet. Three completes a pattern in a way our brains register as "finished," which is exactly what the punchline exploits: the first two items set the expectation, and the third breaks it. A fourth item after that break almost always undercuts the laugh, because the audience already got their payoff at three.', 'gpt-4o', 1223),
    ('f2000000-0000-0000-0000-000000000004', 'f1000000-0000-0000-0000-000000000004', 'As tight as possible — the setup should contain only what''s strictly necessary for the punchline to land. Every extra word is a chance for the audience to drift before the payoff. For your open mic set, read each setup out loud and cut anything that isn''t doing direct work to set up the twist.', 'gpt-4o', 1220),
    ('f2000000-0000-0000-0000-000000000005', 'f1000000-0000-0000-0000-000000000005', 'Not automatically — self-deprecation is safer than punching down at someone else because you''re the author and the target at once, but it isn''t a blanket pass. It becomes contested the moment it relies on a stereotype that reflects on your whole group, not just your own individual experience. The book is careful about that distinction even though it''s easy to summarize past.', 'gpt-4o', 1140),
    ('f2000000-0000-0000-0000-000000000006', 'f1000000-0000-0000-0000-000000000006', 'There''s no fixed count — it''s a feel decision, but the pause should be just long enough to signal a payoff is coming without giving away what it is. Used correctly it amplifies the laugh by building tension; overused, especially with a predictable rhythm, it telegraphs the joke before you say it. Record yourself and listen back — if you can guess your own punchline during the pause, it''s too long.', 'gpt-4o', 1213),
    ('f2000000-0000-0000-0000-000000000007', 'f1000000-0000-0000-0000-000000000007', 'Open fast, reliable, and low-risk to establish credibility quickly. Save your more adventurous or vulnerable material for the middle, once the room has decided to trust you. Close with your strongest bit — highest payoff, most satisfying structure — and never close on experimental material. The last 30 seconds should feel inevitable, like the whole set was building toward it.', 'gpt-4o', 1270),
    ('f2000000-0000-0000-0000-000000000008', 'f1000000-0000-0000-0000-000000000008', 'Two items just read as a list — there''s no real pattern yet. Three completes a pattern in a way our brains register as "finished," which is exactly what the punchline exploits: the first two items set the expectation, and the third breaks it. A fourth item after that break almost always undercuts the laugh, because the audience already got their payoff at three.', 'gpt-4o', 1364),
    ('f2000000-0000-0000-0000-000000000009', 'f1000000-0000-0000-0000-000000000009', 'Macro-timing is set-level — where a bit sits in your running order, how bits are sequenced against each other. Micro-timing is inside a single joke — the millisecond decisions about pauses, emphasis, and pace. Micro-timing is usually what separates a good comedian from a great one, since a pause before a punchline builds tension, but an overused one telegraphs the joke before it lands.', 'gpt-4o', 1443),
    ('f2000000-0000-0000-0000-000000000010', 'f1000000-0000-0000-0000-000000000010', 'Punching up targets people with more social power than you or your audience — institutions, the wealthy, people in charge. Punching down targets people with less power. Audiences are generally more comfortable laughing at power than at vulnerability, which is why punching down reads as riskier. Self-deprecating humor sits in its own category since you hold the authority over your own framing — but it gets contested fast if it leans on stereotypes that affect your whole group, not just you.', 'gpt-4o', 1151),
    ('f2000000-0000-0000-0000-000000000011', 'f1000000-0000-0000-0000-000000000011', 'There''s no fixed count — it''s a feel decision, but the pause should be just long enough to signal a payoff is coming without giving away what it is. Used correctly it amplifies the laugh by building tension; overused, especially with a predictable rhythm, it telegraphs the joke before you say it. Record yourself and listen back — if you can guess your own punchline during the pause, it''s too long.', 'gpt-4o', 1151),
    ('f2000000-0000-0000-0000-000000000012', 'f1000000-0000-0000-0000-000000000012', 'Macro-timing is set-level — where a bit sits in your running order, how bits are sequenced against each other. Micro-timing is inside a single joke — the millisecond decisions about pauses, emphasis, and pace. Micro-timing is usually what separates a good comedian from a great one, since a pause before a punchline builds tension, but an overused one telegraphs the joke before it lands.', 'gpt-4o', 1258),
    ('f2000000-0000-0000-0000-000000000013', 'f1000000-0000-0000-0000-000000000013', 'Punching up targets people with more social power than you or your audience — institutions, the wealthy, people in charge. Punching down targets people with less power. Audiences are generally more comfortable laughing at power than at vulnerability, which is why punching down reads as riskier. Self-deprecating humor sits in its own category since you hold the authority over your own framing — but it gets contested fast if it leans on stereotypes that affect your whole group, not just you.', 'gpt-4o', 1040),
    ('f2000000-0000-0000-0000-000000000014', 'f1000000-0000-0000-0000-000000000014', 'Two things stack on top of each other: recognition (the pleasure of remembering something) and surprise (the return feeling unexpected even though part of you half-anticipated it). The ideal gap is long enough that the audience has partly forgotten the original — usually 5 to 10 minutes in a full set — so the callback rewards people who were paying attention.', 'gpt-4o', 1418),
    ('f2000000-0000-0000-0000-000000000015', 'f1000000-0000-0000-0000-000000000015', 'Misdirection fails when the audience sees the twist coming before you deliver it — if the setup doesn''t fully commit to the false read, there''s no real surprise left for the punchline to provide. The setup has to point confidently at the wrong interpretation so the reveal actually lands as a reveal, not a confirmation.', 'gpt-4o', 1346),
    ('f2000000-0000-0000-0000-000000000016', 'f1000000-0000-0000-0000-000000000016', 'There''s no fixed count — it''s a feel decision, but the pause should be just long enough to signal a payoff is coming without giving away what it is. Used correctly it amplifies the laugh by building tension; overused, especially with a predictable rhythm, it telegraphs the joke before you say it. Record yourself and listen back — if you can guess your own punchline during the pause, it''s too long.', 'gpt-4o', 1425),
    ('f2000000-0000-0000-0000-000000000017', 'f1000000-0000-0000-0000-000000000017', 'A callback only works if the original moment was genuinely memorable on its own — calling back to a weak joke just reminds the audience the joke was weak the first time. Before you plan a callback, ask whether the room actually reacted to the original moment. If it landed, you have material to return to.', 'gpt-4o', 1108),
    ('f2000000-0000-0000-0000-000000000018', 'f1000000-0000-0000-0000-000000000018', 'Punching up targets people with more social power than you or your audience — institutions, the wealthy, people in charge. Punching down targets people with less power. Audiences are generally more comfortable laughing at power than at vulnerability, which is why punching down reads as riskier. Self-deprecating humor sits in its own category since you hold the authority over your own framing — but it gets contested fast if it leans on stereotypes that affect your whole group, not just you.', 'gpt-4o', 1092),
    ('f2000000-0000-0000-0000-000000000019', 'f1000000-0000-0000-0000-000000000019', 'A callback only works if the original moment was genuinely memorable on its own — calling back to a weak joke just reminds the audience the joke was weak the first time. Before you plan a callback, ask whether the room actually reacted to the original moment. If it landed, you have material to return to.', 'gpt-4o', 1326),
    ('f2000000-0000-0000-0000-000000000020', 'f1000000-0000-0000-0000-000000000020', 'Misdirection fails when the audience sees the twist coming before you deliver it — if the setup doesn''t fully commit to the false read, there''s no real surprise left for the punchline to provide. The setup has to point confidently at the wrong interpretation so the reveal actually lands as a reveal, not a confirmation.', 'gpt-4o', 1447),
    ('f2000000-0000-0000-0000-000000000021', 'f1000000-0000-0000-0000-000000000021', 'As tight as possible — the setup should contain only what''s strictly necessary for the punchline to land. Every extra word is a chance for the audience to drift before the payoff. For your open mic set, read each setup out loud and cut anything that isn''t doing direct work to set up the twist.', 'gpt-4o', 1248),
    ('f2000000-0000-0000-0000-000000000022', 'f1000000-0000-0000-0000-000000000022', 'As tight as possible — the setup should contain only what''s strictly necessary for the punchline to land. Every extra word is a chance for the audience to drift before the payoff. For your open mic set, read each setup out loud and cut anything that isn''t doing direct work to set up the twist.', 'gpt-4o', 1369),
    ('f2000000-0000-0000-0000-000000000023', 'f1000000-0000-0000-0000-000000000023', 'In the middle, not the open or the close. The opener''s job is just to establish credibility fast and reliably — that''s not the place to gamble. Once the audience has decided to trust you (usually a minute or two in), that''s your window for the more adventurous material. Save your safest, strongest bit for the close so you leave on a high point.', 'gpt-4o', 1161),
    ('f2000000-0000-0000-0000-000000000024', 'f1000000-0000-0000-0000-000000000024', 'Misdirection fails when the audience sees the twist coming before you deliver it — if the setup doesn''t fully commit to the false read, there''s no real surprise left for the punchline to provide. The setup has to point confidently at the wrong interpretation so the reveal actually lands as a reveal, not a confirmation.', 'gpt-4o', 1417),
    ('f2000000-0000-0000-0000-000000000025', 'f1000000-0000-0000-0000-000000000025', 'A callback only works if the original moment was genuinely memorable on its own — calling back to a weak joke just reminds the audience the joke was weak the first time. Before you plan a callback, ask whether the room actually reacted to the original moment. If it landed, you have material to return to.', 'gpt-4o', 1077),
    ('f2000000-0000-0000-0000-000000000026', 'f1000000-0000-0000-0000-000000000026', 'As tight as possible — the setup should contain only what''s strictly necessary for the punchline to land. Every extra word is a chance for the audience to drift before the payoff. For your open mic set, read each setup out loud and cut anything that isn''t doing direct work to set up the twist.', 'gpt-4o', 1264),
    ('f2000000-0000-0000-0000-000000000027', 'f1000000-0000-0000-0000-000000000027', 'It''s the deliberate construction of a false expectation that the punchline then destroys and replaces. The setup has to make the audience commit to reading it one way; the punchline reveals the correct interpretation, which needs to be both surprising and, in hindsight, clearly present in the setup all along. Done well, the audience feels briefly fooled and then immediately clever for catching up.', 'gpt-4o', 1052),
    ('f2000000-0000-0000-0000-000000000028', 'f1000000-0000-0000-0000-000000000028', 'Punching up targets people with more social power than you or your audience — institutions, the wealthy, people in charge. Punching down targets people with less power. Audiences are generally more comfortable laughing at power than at vulnerability, which is why punching down reads as riskier. Self-deprecating humor sits in its own category since you hold the authority over your own framing — but it gets contested fast if it leans on stereotypes that affect your whole group, not just you.', 'gpt-4o', 1308),
    ('f2000000-0000-0000-0000-000000000029', 'f1000000-0000-0000-0000-000000000029', 'Voice isn''t invented, it''s excavated — it shows up from writing and performing consistently and noticing which material feels authentically yours versus borrowed. A few signals you''ve found it: you write jokes only you would write, performing your material feels effortless instead of performed, and other comedians could identify your work without a byline.', 'gpt-4o', 1433),
    ('f2000000-0000-0000-0000-000000000030', 'f1000000-0000-0000-0000-000000000030', 'Open fast, reliable, and low-risk to establish credibility quickly. Save your more adventurous or vulnerable material for the middle, once the room has decided to trust you. Close with your strongest bit — highest payoff, most satisfying structure — and never close on experimental material. The last 30 seconds should feel inevitable, like the whole set was building toward it.', 'gpt-4o', 984),
    ('f2000000-0000-0000-0000-000000000031', 'f1000000-0000-0000-0000-000000000031', 'It''s the deliberate construction of a false expectation that the punchline then destroys and replaces. The setup has to make the audience commit to reading it one way; the punchline reveals the correct interpretation, which needs to be both surprising and, in hindsight, clearly present in the setup all along. Done well, the audience feels briefly fooled and then immediately clever for catching up.', 'gpt-4o', 1256),
    ('f2000000-0000-0000-0000-000000000032', 'f1000000-0000-0000-0000-000000000032', 'A callback only works if the original moment was genuinely memorable on its own — calling back to a weak joke just reminds the audience the joke was weak the first time. Before you plan a callback, ask whether the room actually reacted to the original moment. If it landed, you have material to return to.', 'gpt-4o', 1204),
    ('f2000000-0000-0000-0000-000000000033', 'f1000000-0000-0000-0000-000000000033', 'Four theories: Incongruity (humor from conflicting ideas resolved by the punchline), Superiority (laughing at others'' misfortune or inferiority — Hobbes, Plato), Relief (laughter releasing suppressed tension — Freud, Spencer), and Bergson''s social-corrective theory (laughing at rigidity to nudge people back toward flexibility). Reference whichever framework best explains the specific joke you''re analysing — most jokes lean on more than one.', 'gpt-4o', 1376),
    ('f2000000-0000-0000-0000-000000000034', 'f1000000-0000-0000-0000-000000000034', 'Open fast, reliable, and low-risk to establish credibility quickly. Save your more adventurous or vulnerable material for the middle, once the room has decided to trust you. Close with your strongest bit — highest payoff, most satisfying structure — and never close on experimental material. The last 30 seconds should feel inevitable, like the whole set was building toward it.', 'gpt-4o', 1442),
    ('f2000000-0000-0000-0000-000000000035', 'f1000000-0000-0000-0000-000000000035', 'The tag is an optional second beat that comes right after the punchline and extends the laugh with one more unexpected turn. It''s not required — a joke works fine with just setup and punchline — but a good tag squeezes extra value out of a premise the audience is already primed for. The risk is stacking too many tags: each one has to earn its place, or it just dilutes the original laugh.', 'gpt-4o', 1293),
    ('f2000000-0000-0000-0000-000000000036', 'f1000000-0000-0000-0000-000000000036', 'In the middle, not the open or the close. The opener''s job is just to establish credibility fast and reliably — that''s not the place to gamble. Once the audience has decided to trust you (usually a minute or two in), that''s your window for the more adventurous material. Save your safest, strongest bit for the close so you leave on a high point.', 'gpt-4o', 986),
    ('f2000000-0000-0000-0000-000000000037', 'f1000000-0000-0000-0000-000000000037', 'Observational comedy starts from shared reality — things everyone has experienced — and finds the funny angle inside it; the comedian acts like a mirror held at a slightly distorted angle. Absurdist comedy starts from a premise that violates reality and follows that violation to its most logical conclusion, generating comedy from the collision between an impossible premise and rigorous logic. Observational invites recognition; absurdist invites disorientation.', 'gpt-4o', 1110),
    ('f2000000-0000-0000-0000-000000000038', 'f1000000-0000-0000-0000-000000000038', 'Three items feel like a complete pattern to the human brain in a way two or four don''t. The first two items establish the pattern; the third breaks it, and that break is the joke. Adding a fourth item after a successful three-beat punchline almost always deflates the laugh — the audience already got their payoff.', 'gpt-4o', 1104),
    ('f2000000-0000-0000-0000-000000000039', 'f1000000-0000-0000-0000-000000000039', 'Incongruity Theory says humor comes from holding two conflicting ideas at once, resolved by the punchline. Superiority Theory (Hobbes, Plato) says laughter is a response to perceiving someone else''s misfortune or inferiority. Relief Theory (Freud, Spencer) says laughter releases suppressed tension. Bergson''s theory frames laughter as a social corrective — mocking rigidity to push people back toward flexibility. None fully explains humor alone, but each captures something real.', 'gpt-4o', 1354),
    ('f2000000-0000-0000-0000-000000000040', 'f1000000-0000-0000-0000-000000000040', 'Misdirection fails when the audience sees the twist coming before you deliver it — if the setup doesn''t fully commit to the false read, there''s no real surprise left for the punchline to provide. The setup has to point confidently at the wrong interpretation so the reveal actually lands as a reveal, not a confirmation.', 'gpt-4o', 1347),
    ('f2000000-0000-0000-0000-000000000041', 'f1000000-0000-0000-0000-000000000041', 'Three items feel like a complete pattern to the human brain in a way two or four don''t. The first two items establish the pattern; the third breaks it, and that break is the joke. Adding a fourth item after a successful three-beat punchline almost always deflates the laugh — the audience already got their payoff.', 'gpt-4o', 993),
    ('f2000000-0000-0000-0000-000000000042', 'f1000000-0000-0000-0000-000000000042', 'Voice isn''t invented, it''s excavated — it shows up from writing and performing consistently and noticing which material feels authentically yours versus borrowed. A few signals you''ve found it: you write jokes only you would write, performing your material feels effortless instead of performed, and other comedians could identify your work without a byline.', 'gpt-4o', 1163),
    ('f2000000-0000-0000-0000-000000000043', 'f1000000-0000-0000-0000-000000000043', 'Incongruity Theory says humor comes from holding two conflicting ideas at once, resolved by the punchline. Superiority Theory (Hobbes, Plato) says laughter is a response to perceiving someone else''s misfortune or inferiority. Relief Theory (Freud, Spencer) says laughter releases suppressed tension. Bergson''s theory frames laughter as a social corrective — mocking rigidity to push people back toward flexibility. None fully explains humor alone, but each captures something real.', 'gpt-4o', 1326),
    ('f2000000-0000-0000-0000-000000000044', 'f1000000-0000-0000-0000-000000000044', 'Two items just read as a list — there''s no real pattern yet. Three completes a pattern in a way our brains register as "finished," which is exactly what the punchline exploits: the first two items set the expectation, and the third breaks it. A fourth item after that break almost always undercuts the laugh, because the audience already got their payoff at three.', 'gpt-4o', 1286),
    ('f2000000-0000-0000-0000-000000000045', 'f1000000-0000-0000-0000-000000000045', 'The tag is an optional second beat that comes right after the punchline and extends the laugh with one more unexpected turn. It''s not required — a joke works fine with just setup and punchline — but a good tag squeezes extra value out of a premise the audience is already primed for. The risk is stacking too many tags: each one has to earn its place, or it just dilutes the original laugh.', 'gpt-4o', 1250),
    ('f2000000-0000-0000-0000-000000000046', 'f1000000-0000-0000-0000-000000000046', 'Observational comedy starts from shared reality — things everyone has experienced — and finds the funny angle inside it; the comedian acts like a mirror held at a slightly distorted angle. Absurdist comedy starts from a premise that violates reality and follows that violation to its most logical conclusion, generating comedy from the collision between an impossible premise and rigorous logic. Observational invites recognition; absurdist invites disorientation.', 'gpt-4o', 982),
