INSERT INTO answers (id, question_id, content, model_used, generation_latency_ms) VALUES ('f2000000-0000-0000-0000-000000000096', 'f1000000-0000-0000-0000-000000000096', 'Building on the earlier thread: the same principle applies, but scale your expectations to the room and the set length — what works in a 20-minute set often needs to be compressed or cut entirely in a 5-minute one. Try it on stage in a low-stakes room first and adjust based on what actually gets a reaction, not what you expect to.', 'gpt-4o', 1131);
